using System;using System.Drawing;using System.Windows.Forms;using System.IO;
class TavernCameraChecks {
 [STAThread]static void Main(){string folder=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"assets/tavern/management");using(var art=Image.FromFile(Path.Combine(folder,"hall-forest-panorama.png")))using(var c=new TavernHallCanvas{Width=1100,Height=700,RightPaneWidth=380,Panorama=true,Art=art,State=TavernHall.State(new Save())}){c.LoadWalking(folder);c.State.guests.Add(new HallGuest{id=1,table=0,stage=4});using(var b=new Bitmap(1100,700)){c.DrawToBitmap(b,new Rectangle(0,0,1100,700));b.Save("output/kitchen-layout/game-hall-camera.png");}float start=c.CameraX;c.MoveCamera(200,100);if(c.CameraX<=start)throw new Exception("pan right");var p=new PointF(800,700);var q=c.WorldToHall(c.HallToWorld(p));if(Math.Abs(p.X-q.X)+Math.Abs(p.Y-q.Y)>.1)throw new Exception("coordinate inverse");c.MoveCamera(99999,99999);if(c.CameraX>=art.Width||c.CameraY>=art.Height)throw new Exception("bounds");using(var b=new Bitmap(1100,700)){c.DrawToBitmap(b,new Rectangle(0,0,1100,700));b.Save("output/kitchen-layout/game-kitchen-camera.png");}c.MoveCamera(-99999,-99999);if(c.CameraX!=0||c.CameraY!=0)throw new Exception("negative bounds");}Console.WriteLine("PASS camera render, pan limits, coordinate inverse");}
}
